"""Last-Write-Wins Element Set (LWW-Element-Set) CRDT."""

from dataclasses import dataclass, field
from typing import Any, Dict, Set


class LWWElementSet:
    def __init__(self):
        self.add_set: Dict[str, float] = {}     # element -> timestamp
        self.remove_set: Dict[str, float] = {}  # element -> timestamp

    def add(self, element: str, timestamp: float) -> None:
        curr = self.add_set.get(element, 0.0)
        if timestamp > curr:
            self.add_set[element] = timestamp

    def remove(self, element: str, timestamp: float) -> None:
        curr = self.remove_set.get(element, 0.0)
        if timestamp > curr:
            self.remove_set[element] = timestamp

    def lookup(self, element: str) -> bool:
        add_ts = self.add_set.get(element)
        if add_ts is None:
            return False
        rem_ts = self.remove_set.get(element)
        if rem_ts is None:
            return True
        # LWW-Add-Bias Specification: When add_ts == rem_ts, addition wins (add_ts >= rem_ts)
        # BUG: Uses strict > which favors removal on timestamp ties!
        return add_ts > rem_ts

    def merge(self, other: "LWWElementSet") -> None:
        for el, ts in other.add_set.items():
            self.add(el, ts)
        for el, ts in other.remove_set.items():
            self.remove(el, ts)

