"""Distributed node replica storing CRDT sets."""

from lww_element_set import LWWElementSet


class ReplicaNode:
    def __init__(self, node_id: str):
        self.node_id = node_id
        self.set_crdt = LWWElementSet()

    def sync_with(self, peer: "ReplicaNode") -> None:
        self.set_crdt.merge(peer.set_crdt)

